    if (ql <= l && r <= qr) {
        cnt[node] += v;
    } else {
        int mid = (l + r) / 2;
        if (ql <= mid) update(2 * node, l, mid, ql, qr, v);
        if (qr > mid) update(2 * node + 1, mid + 1, r, ql, qr, v);
    }
    if (cnt[node] > 0) length[node] = ys[r + 1] - ys[l];
    else if (l == r) length[node] = 0;
    else length[node] = length[2 * node] + length[2 * node + 1];
}

